import random
import textwrap

# Generator for valid JavaScript source code exercising diverse language features
# Fixed recursion: strictly respect a maximum depth budget and avoid calling
# unbounded template->expr->template cycles. All recursive constructors receive
# and pass down a decreasing depth counter; when it reaches zero, only leaf
# literals are produced.

JS_IDENT_UNICODE = [
    "α", "β", "γ", "δ", "λ", "Ω", "Ж", "Й", "你", "好", "🙂"
]

LIPSUM_WORDS = (
    "alpha beta gamma delta epsilon zeta eta theta iota kappa lambda mu nu xi omicron "
    "pi rho sigma tau upsilon phi chi psi omega"
).split()

MAX_DEPTH = 3


def _rand_ident(rng: random.Random, prefix: str = "v") -> str:
    base = prefix + str(rng.randrange(0, 1000))
    if rng.random() < 0.5:
        base += rng.choice(JS_IDENT_UNICODE)
    return base


def _rand_string(rng: random.Random) -> str:
    # Mix of quotes and escapes, ensure validity
    choices = [
        "simple",
        "with spaces",
        "line\\nbreak",
        "tab\\tchar",
        "quote ' \" both",
        "backtick-like",
        "unicode: Ω你🙂",
        "slash \\\\",
    ]
    s = rng.choice(choices)
    quote = rng.choice(['"', "'"])
    return f"{quote}{s}{quote}"


def _rand_number(rng: random.Random) -> str:
    kind = rng.choice(["int", "hex", "float", "exp", "bin", "octal"])
    if kind == "int":
        return str(rng.randrange(-2**31, 2**31-1))
    if kind == "hex":
        return hex(rng.randrange(0, 2**32))
    if kind == "float":
        return f"{rng.uniform(-1e6, 1e6):.6f}"
    if kind == "exp":
        return f"{rng.uniform(1, 1e3):.3e}"
    if kind == "bin":
        return "0b" + format(rng.randrange(0, 1<<16), "b")
    return "0o" + format(rng.randrange(0, 1<<16), "o")


def _leaf_expr(rng: random.Random) -> str:
    return rng.choice([
        _rand_string(rng),
        _rand_number(rng),
        "true", "false", "null",
    ])


def _rand_expr(rng: random.Random, depth: int) -> str:
    if depth <= 0:
        return _leaf_expr(rng)

    choice = rng.random()
    if choice < 0.18:
        return _rand_string(rng)
    if choice < 0.36:
        return _rand_number(rng)
    if choice < 0.52:
        return _rand_array(rng, depth - 1)
    if choice < 0.68:
        return _rand_object(rng, depth - 1)
    if choice < 0.80:
        return _rand_template_leafy(rng, depth - 1)

    # function or arrow or call chain or parenthesized
    kind = rng.choice(["arrow", "fn", "call", "paren"])
    if kind == "arrow":
        a = _rand_ident(rng, "a")
        b = _rand_ident(rng, "b")
        body = _rand_expr(rng, depth - 1)
        return f"({a}, {b}) => ({body})"
    if kind == "fn":
        name = _rand_ident(rng, "f")
        p = ", ".join(_rand_ident(rng, "p") for _ in range(rng.randint(0, 3)))
        return f"function {name}({p}) {{ return {_rand_expr(rng, depth - 1)}; }}"
    if kind == "call":
        callee = rng.choice(["Math.max", "String", "Number", "Boolean", "Date", "JSON.stringify"])  # builtins
        args = ", ".join(_rand_expr(rng, depth - 1) for _ in range(rng.randint(0, 3)))
        return f"{callee}({args})"
    return f"({_rand_expr(rng, depth - 1)})"


def _rand_array(rng: random.Random, depth: int) -> str:
    n = rng.randint(0, 6)
    vals = []
    for _ in range(n):
        vals.append(_rand_expr(rng, depth))
    if n and rng.random() < 0.3:
