    return "[" + ", ".join(v for v in vals) + "]"


def _rand_object(rng: random.Random, depth: int) -> str:
    n = rng.randint(0, 6)
    kv = []
    for _ in range(n):
        k = rng.choice([
            _rand_ident(rng, "k"),
            _rand_string(rng),
