    if rng.random() < 0.9:
        import json as _json
        jkeys = [rng.choice(["a", "b", "c", "Ω", "你好"]), rng.choice(["x", "y", "z"])]
        jobj = {jkeys[0]: rng.randint(0, 10), jkeys[1]: rng.choice([True, False, None])}
        jtxt = _json.dumps(jobj, ensure_ascii=False)
        lines.append(f"var jsonText = {repr(jtxt)};")
        lines.append("var parsed = JSON.parse(jsonText);")

    rx = rng.choice([r"/a+b?/gi", r"/^[A-Za-z_][A-Za-z0-9_]*$/", r"/Ω+/u", r"/\\d{2,4}/"])
    lines.append(f"var _m = {rx}.test('alpha123Ω');")

    lines.append(f"const msg = {_rand_template_leafy(rng, MAX_DEPTH)};")

    lines.append("var arr = [1,2,3,4]; arr[2] = arr[1] + 5;")
    lines.append("var obj = {k: 1, nested: {n: 2}}; obj.k += obj.nested.n;")

    if rng.random() < 0.4:
        s = _rand_string(rng)
        lines.append(f"eval({s});")

    lines.append("typeof msg + String(_m) + (arr[2]||'')")

    return "\n".join(lines)


def _make_module(rng: random.Random) -> str:
    lines = []
    lines.append("export const fortyTwo = 42;")
    name = _rand_ident(rng, "mod")
    lines.append(f"export function {name}(x) {{ return x ?? fortyTwo; }}")
    lines.append("export default class D { constructor(v){ this.v=v } get v2(){ return this.v*2 } }")
    lines.append("\n// usage inside module scope\n")
    lines.append("const _tmp = new D(fortyTwo);")
    lines.append("_tmp.v2;")
    return "\n".join(lines)


def _truncate_bytes(b: bytes, limit: int = 4096) -> bytes:
    if len(b) <= limit:
        return b
    cut = b.rfind(b"\n", 0, limit)
    if cut == -1:
        cut = limit
    return b[:cut]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    mode = rng.choices(
        population=["program", "module", "json", "expr"],
        weights=[0.55, 0.15, 0.15, 0.15],
        k=1,
    )[0]

    if mode == "json":
        import json as _json
        obj = {
            "words": rng.sample(LIPSUM_WORDS, rng.randint(2, min(6, len(LIPSUM_WORDS)))),
            "nums": [rng.randint(-100, 100) for _ in range(rng.randint(2, 6))],
            "flag": rng.choice([True, False]),
            "nested": {"k": rng.randint(0, 9)},
        }
        txt = _json.dumps(obj, ensure_ascii=False)
    elif mode == "module":
        txt = _make_module(rng)
    elif mode == "expr":
        txt = _rand_expr(rng, MAX_DEPTH)
    else:
        txt = _make_program(rng)

    data = txt.encode("utf-8", errors="strict")
    return _truncate_bytes(data, 4096)
